-- ANALYTICS-NULL-1 (2026-11-14, charter pillar reach; found by reading the first live run, then by the review gate on PR 11817). printf('%.2f', NULL) is '0.00', so analytics_trend_precision_28d read 0.00 with no settled finding at all
-- and ga4_consent_share_7d would read 0.0000 if the cookie-free counter ever had no rows: "no data yet" looked like a measured zero. Both refresh steps now write NULL when there is nothing to measure.
-- The merged migrations are not edited (MIGRATION-NO-CLOBBER-1); this one replaces the two tasks and clears the value already written.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name IN ('analytics-loop-hourly', 'ga4-consent-share-hourly'); UPDATE fleet_tasks SET enabled = 0 WHERE id IN ('analytics-loop', 'ga4-consent-share');

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('analytics-loop', 'ANALYTICS-LOOP-1: Cloudflare analytics to findings, actions, settle and tune (SQL only)', 'workflow', '{"steps": [{"type": "sql", "name": "findings", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO analytics_findings (kind, entity, window_end, v7, v_prev7, ext7, predicted, status, created_at) SELECT t.kind, t.slug, date(''now''), t.v7, t.v_prev7, t.ext7, CASE WHEN t.kind = ''fading'' THEN ''next7 <= 1.5 * v7'' ELSE ''next7 >= 0.5 * v7'' END, ''open'', datetime(''now'') FROM v_analytics_paper_trend t WHERE t.kind IS NOT NULL AND NOT EXISTS (SELECT 1 FROM analytics_findings f WHERE f.entity = t.slug AND f.kind = t.kind AND f.created_at >= datetime(''now'',''-7 days''))"}, {"type": "sql", "name": "act_research", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO research_queue (id, source, source_id, idea, summary, score, decision, status, created_at) SELECT ''an-'' || f.id, ''analytics'', f.entity || ''@'' || f.window_end, ''Demand-led follow-up to the published paper \"'' || f.entity || ''\": readers are arriving now ('' || CAST(f.v7 AS INTEGER) || '' views in 7 days, '' || CAST(f.ext7 AS INTEGER) || '' from outside the fleet). Extend it with the next question a reader of this paper would ask.'', ''analytics-loop '' || f.kind || '': '' || CAST(f.v7 AS INTEGER) || '' views in 7 days against '' || CAST(f.v_prev7 AS INTEGER) || '' before.'', 0.95, ''ACCEPT'', ''queued'', datetime(''now'') FROM analytics_findings f WHERE f.status = ''open'' AND f.kind IN (''rising'',''external_pull'') AND NOT EXISTS (SELECT 1 FROM analytics_findings g WHERE g.entity = f.entity AND g.status = ''acted'' AND g.created_at >= datetime(''now'',''-14 days'')) ORDER BY (f.ext7 * 3 + f.v7) DESC LIMIT MAX(0, 2 - (SELECT COUNT(*) FROM analytics_findings h WHERE h.status = ''acted'' AND h.action LIKE ''research_queue%'' AND date(h.created_at) = date(''now'')))"}, {"type": "sql", "name": "mark_acted", "db": "AUDIT", "sql": "UPDATE analytics_findings SET status = ''acted'', action = ''research_queue follow-up'', action_ref = ''an-'' || id WHERE status = ''open'' AND EXISTS (SELECT 1 FROM research_queue r WHERE r.id = ''an-'' || analytics_findings.id)"}, {"type": "sql", "name": "mark_fading", "db": "AUDIT", "sql": "UPDATE analytics_findings SET status = ''acted'', action = ''decay recorded; settles in 8 days and tunes the thresholds'', action_ref = NULL WHERE status = ''open'' AND kind = ''fading''"}, {"type": "sql", "name": "settle_observe", "db": "AUDIT", "sql": "UPDATE analytics_findings SET observed = (SELECT COALESCE(SUM(s.value), 0) FROM reach_signals s WHERE s.source = ''cf-rum-human'' AND s.entity_type = ''paper'' AND s.metric = ''pageviews'' AND s.entity_id = analytics_findings.entity AND s.date >= date(analytics_findings.created_at) AND s.date < date(analytics_findings.created_at, ''+7 days'')), status = ''settled'', settled_at = datetime(''now'') WHERE status IN (''open'',''acted'') AND created_at <= datetime(''now'',''-8 days'')"}, {"type": "sql", "name": "settle_outcome", "db": "AUDIT", "sql": "UPDATE analytics_findings SET outcome = CASE WHEN (kind = ''fading'' AND observed <= 1.5 * v7) OR (kind <> ''fading'' AND observed >= 0.5 * v7) THEN ''held'' ELSE ''missed'' END WHERE status = ''settled'' AND outcome IS NULL"}, {"type": "sql", "name": "tune_threshold", "db": "AUDIT", "sql": "UPDATE ops_config SET value = CAST(CASE WHEN (SELECT COUNT(*) FROM (SELECT outcome FROM analytics_findings WHERE kind = ''rising'' AND status = ''settled'' ORDER BY settled_at DESC LIMIT 20)) >= 10 AND (SELECT AVG(outcome = ''held'') FROM (SELECT outcome FROM analytics_findings WHERE kind = ''rising'' AND status = ''settled'' ORDER BY settled_at DESC LIMIT 20)) < 0.5 THEN ROUND(CAST(value AS REAL) * 1.25) WHEN (SELECT COUNT(*) FROM (SELECT outcome FROM analytics_findings WHERE kind = ''rising'' AND status = ''settled'' ORDER BY settled_at DESC LIMIT 20)) >= 10 AND (SELECT AVG(outcome = ''held'') FROM (SELECT outcome FROM analytics_findings WHERE kind = ''rising'' AND status = ''settled'' ORDER BY settled_at DESC LIMIT 20)) > 0.8 THEN MAX(5, ROUND(CAST(value AS REAL) * 0.9)) ELSE CAST(value AS REAL) END AS INTEGER), note = ''ANALYTICS-LOOP-1: the minimum 7-day views that make a paper rising; raised 25 percent when under half of the last 20 settled rising findings held, lowered 10 percent when over 80 percent did'', updated_at = datetime(''now'') WHERE key = ''analytics_rise_min_views'' AND updated_at < COALESCE((SELECT MAX(settled_at) FROM analytics_findings WHERE kind = ''rising'' AND status = ''settled''), '''')"}, {"type": "sql", "name": "metric_precision", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = (SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE printf(''%.2f'', AVG(outcome = ''held'')) END FROM analytics_findings WHERE status = ''settled'' AND settled_at >= datetime(''now'',''-28 days'')), last_refreshed = datetime(''now'') WHERE metric = ''analytics_trend_precision_28d''"}, {"type": "sql", "name": "metric_actions", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM analytics_findings WHERE status IN (''acted'',''settled'') AND action LIKE ''research_queue%'' AND created_at >= datetime(''now'',''-7 days'')) AS TEXT), last_refreshed = datetime(''now'') WHERE metric = ''analytics_actions_7d''"}]}', 60000, 1, 2, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('ga4-consent-share', 'GA4-CONSENT-SHARE-1: refresh the GA4 share of cookie-free page views (SQL only)', 'workflow', '{"steps": [{"type": "sql", "name": "refresh", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CASE WHEN COALESCE((SELECT SUM(value) FROM reach_signals WHERE source = ''cf-rum-human'' AND entity_type = ''host'' AND metric = ''pageviews'' AND date >= date(''now'',''-7 days'')), 0) > 0 THEN printf(''%.4f'', COALESCE((SELECT SUM(value) FROM reach_signals WHERE source = ''ga4'' AND entity_type = ''host'' AND metric = ''screenPageViews'' AND date >= date(''now'',''-7 days'')), 0) * 1.0 / (SELECT SUM(value) FROM reach_signals WHERE source = ''cf-rum-human'' AND entity_type = ''host'' AND metric = ''pageviews'' AND date >= date(''now'',''-7 days''))) ELSE NULL END, last_refreshed = datetime(''now'') WHERE metric = ''ga4_consent_share_7d''"}]}', 30000, 1, 2, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

UPDATE metric_registry SET last_value = NULL, last_refreshed = datetime('now') WHERE metric = 'analytics_trend_precision_28d' AND NOT EXISTS (SELECT 1 FROM analytics_findings WHERE status = 'settled');
